import functools, itertools, operator, sys
sys.setrecursionlimit(100000)
def solver(moves):
    @functools.lru_cache(None)
    def win(s): return any(not win(t) for t in moves(s))
    return win
def reach_set(start, moves):
    seen, todo = {start}, [start]
    while todo:
        s = todo.pop()
        for t in moves(s):
            if t not in seen: seen.add(t); todo.append(t)
    return seen
w = solver(lambda n: tuple(n - k for k in (1, 3, 4) if k <= n))
result = sum(1 for n in range(1, 1001) if not w(n))

